export type ServiceName = keyof typeof SERVICE_LOGOS;

export interface ServiceLogoProps extends Omit<React.SVGProps<SVGSVGElement>, "name" | "children"> {
  name: ServiceName;
  /** Height in px; width follows the mark's own proportions. */
  size?: number;
  /** Accessible name. Leave unset when the service name is visible next to the mark. */
  title?: string;
}

/** A service's own logo. Gradient ids are made unique per instance, so the same mark can repeat on a page. */
export function ServiceLogo({ name, size = 16, title, ...props }: ServiceLogoProps) {
  const uid = React.useId().replace(/:/g, "");
  const mark = SERVICE_LOGOS[name];
  const body = React.useMemo(
    () => mark.body.replace(/id="([^"]+)"/g, `id="${uid}$1"`).replace(/url\(#([^)]+)\)/g, `url(#${uid}$1)`).replace(/href="#([^"]+)"/g, `href="#${uid}$1"`),
    [mark.body, uid],
  );
  const a11y = title ? { role: "img", "aria-label": title } : { "aria-hidden": true, focusable: "false" as const };
  return (
    <svg
      viewBox={`0 0 ${mark.w} ${mark.h}`}
      height={size}
      width={(size * mark.w) / mark.h}
      fill="currentColor"
      {...a11y}
      {...props}
      dangerouslySetInnerHTML={{ __html: body }}
    />
  );
}
